-- migration_012_new_questions_sept2026b.sql
-- Batch 2 of new MTF questions from "Questions to add.pdf": ANS pharmacology
-- (noradrenaline reuptake), nociceptor sensitisation, inhibitory
-- neurotransmitters in the pain pathway, dorsal horn cytoarchitecture,
-- central sensitisation, conventional TENS, amitriptyline, botulinum toxin,
-- MRI physics, and imaging modalities. Several carry knowledge boxes with
-- zoomable reference tables/figures and one embedded video.
--
-- Safe to run directly in the Supabase SQL Editor. Idempotent (on conflict do
-- nothing) so it can be re-run harmlessly. No new categories are introduced.

insert into questions (id, type, data, status) values ('q_mtf_noradrenaline_reuptake_001', 'MTF', '{"dateAdded":"2026-09-05","rotationIndex":71,"stem":"Noradrenaline neurotransmitter reuptake happens through:","choices":["Oxidative degradation","Enzymatic degradation","Hydrolysis","Reuptake by the presynaptic neuron","Diffusion into the vascular circulation"],"correct":[true,true,false,true,true],"explanation":"<p>Termination of noradrenaline''s action at the sympathetic synapse occurs through several complementary mechanisms, rather than a single dominant process.</p>\n<p style=\"margin-top:12px\"><strong>A. TRUE</strong> — Noradrenaline undergoes oxidative degradation via <strong>monoamine oxidase (MAO)</strong>, located on the outer mitochondrial membrane within the presynaptic neuron, converting noradrenaline into inactive metabolites.</p>\n<p style=\"margin-top:12px\"><strong>B. TRUE</strong> — Noradrenaline also undergoes enzymatic degradation via <strong>catechol-O-methyltransferase (COMT)</strong>, located extraneuronally (postsynaptically and in other tissues such as the liver), methylating noradrenaline into inactive metabolites (normetanephrine and ultimately VMA).</p>\n<p style=\"margin-top:12px\"><strong>C. FALSE</strong> — Hydrolysis is not a relevant mechanism for noradrenaline termination — this describes the mechanism by which <strong>acetylcholine</strong> is broken down by acetylcholinesterase at cholinergic synapses, not the mechanism for catecholamine neurotransmitters like noradrenaline.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> — Reuptake by the presynaptic neuron (<strong>Uptake-1</strong>, via the noradrenaline transporter, NET) is the <strong>most significant and rapid mechanism</strong> terminating noradrenaline''s synaptic action, recycling the majority of released noradrenaline back into presynaptic storage vesicles for re-use.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> — A proportion of released noradrenaline <strong>diffuses away from the synaptic cleft into the surrounding vasculature/extracellular fluid</strong> (sometimes termed \"Uptake-2\" when taken up by non-neuronal tissues, or simple diffusional loss into the circulation), where it is diluted and eventually metabolised systemically (e.g. hepatic MAO/COMT), contributing modestly to termination of its local synaptic effect.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Autonomic Nervous System</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Combined Reference Table</div><table style=\"margin:0\"><tr><th>Feature</th><th>Sympathetic</th><th>Parasympathetic</th></tr><tr><td>Spinal outflow</td><td>Thoracolumbar (T1&ndash;L2)</td><td>Craniosacral (CN III, VII, IX, X; S2&ndash;S4)</td></tr><tr><td>Preganglionic neuron length</td><td>Short</td><td>Long</td></tr><tr><td>Preganglionic neurotransmitter</td><td>Acetylcholine</td><td>Acetylcholine</td></tr><tr><td>Preganglionic receptor (on ganglion)</td><td>Nicotinic (N<sub>n</sub>)</td><td>Nicotinic (N<sub>n</sub>)</td></tr><tr><td>Ganglion location</td><td>Close to spinal cord (paravertebral chain / prevertebral ganglia, e.g. coeliac, mesenteric)</td><td>Close to, or within, the target organ wall (e.g. cardiac plexus, myenteric plexus, ciliary ganglion)</td></tr><tr><td>Postganglionic neuron length</td><td>Long</td><td>Short</td></tr><tr><td>Postganglionic neurotransmitter (most targets)</td><td>Noradrenaline</td><td>Acetylcholine</td></tr><tr><td>Postganglionic receptor (most targets)</td><td>Alpha (&alpha;1, &alpha;2) / Beta (&beta;1, &beta;2, &beta;3) adrenoreceptors</td><td>Muscarinic (M1&ndash;M5)</td></tr><tr><td>Exception &mdash; sweat glands (eccrine)</td><td>Sympathetic, but the postganglionic transmitter is <strong>acetylcholine</strong> &rarr; muscarinic receptors</td><td>&mdash;</td></tr><tr><td>Exception &mdash; adrenal medulla</td><td>Preganglionic fibre synapses <strong>directly</strong> on chromaffin cells (no postganglionic neuron); releases ACh &rarr; nicotinic receptors; chromaffin cells then secrete adrenaline (~80%) and noradrenaline (~20%) into the bloodstream as hormones</td><td>&mdash;</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Neurotransmitters &amp; receptors of the pre- and postganglionic neurons</div><div style=\"text-align:center\"><img src=\"images/autonomic-preganglionic-postganglionic-neurons.png\" alt=\"Diagram comparing the parasympathetic and sympathetic nervous systems — preganglionic and postganglionic fibre lengths with acetylcholine, noradrenaline, nicotinic, muscarinic and adrenergic receptors marked\" style=\"max-width:100%;border-radius:10px;margin-top:0;border:1px solid #EDE3D7\"></div></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_nociceptor_sensitisation_001', 'MTF', '{"dateAdded":"2026-09-05","rotationIndex":72,"stem":"Nociceptors are sensitised by:","choices":["Acetylcholine","Potassium","ATP","Prostaglandins","Substance P"],"correct":[false,true,true,true,true],"explanation":"<p>Peripheral sensitisation occurs when tissue damage/inflammation releases a mixture of chemical mediators &mdash; often termed the \"inflammatory soup\" &mdash; that act directly on nociceptor terminals to lower their activation threshold and/or increase their responsiveness, contributing to primary hyperalgesia.</p>\n<p style=\"margin-top:12px\"><strong>A. FALSE</strong> — Acetylcholine is not a classical component of the inflammatory soup implicated in nociceptor sensitisation; its physiological role relates to autonomic/neuromuscular transmission rather than peripheral pain sensitisation.</p>\n<p style=\"margin-top:12px\"><strong>B. TRUE</strong> — Potassium (K<sup>+</sup>) is released from damaged cells and directly activates as well as sensitises nociceptor terminals, lowering the threshold for action potential generation.</p>\n<p style=\"margin-top:12px\"><strong>C. TRUE</strong> — ATP, released from damaged cells, acts on <strong>P2X</strong> (ligand-gated ion channel) and <strong>P2Y</strong> (GPCR) purinergic receptors on nociceptor terminals, contributing directly to sensitisation and pain signalling.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> — Prostaglandins (particularly PGE2), synthesised via the cyclooxygenase pathway from arachidonic acid, sensitise nociceptors by lowering their activation threshold (largely via a second-messenger-mediated reduction in the threshold of voltage-gated sodium channels) &mdash; the basis for NSAID/COX-inhibitor analgesic action.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> — Substance P, released from nociceptor terminals themselves (part of \"neurogenic inflammation\"), acts on <strong>NK1 receptors</strong>, contributing to vasodilation, plasma extravasation, and mast cell degranulation, amplifying local sensitisation in a feed-forward manner.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Inflammatory soup</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><table style=\"margin:0\"><tr><th colspan=\"3\" style=\"text-align:center\">Endogenous inflammatory mediators</th></tr><tr><td><strong>Substance</strong></td><td><strong>Source</strong></td><td><strong>Effect on nociceptor</strong></td></tr><tr><td>Potassium</td><td>Damaged cells</td><td>Activation</td></tr><tr><td>Protons</td><td>Hypoxic cells</td><td>Activation</td></tr><tr><td>Serotonin (5-HT)</td><td>Platelets</td><td>Activation</td></tr><tr><td>Bradykinin</td><td>Plasma kininogen</td><td>Activation</td></tr><tr><td>Histamine</td><td>Mast cells</td><td>Activation</td></tr><tr><td>Prostanoids</td><td>Damaged cells</td><td>Sensitization</td></tr><tr><td>Leukotrienes</td><td>Damaged cells</td><td>Sensitization</td></tr><tr><td>Substance P</td><td>Primary afferents</td><td>Sensitization</td></tr><tr><td>CGRP</td><td>Primary afferents</td><td>Sensitization</td></tr><tr><td>Glutamate</td><td>Primary afferents</td><td>Sensitization</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_inhibitory_neurotransmitters_pain_001', 'MTF', '{"dateAdded":"2026-09-05","rotationIndex":73,"stem":"The following neurotransmitters are inhibitory within the pain pathway in the CNS:","choices":["Acetylcholine","Glycine","GABA","Glutamate","Noradrenaline"],"correct":[true,true,true,false,true],"explanation":"<p>Inhibitory control of pain transmission in the CNS occurs both segmentally (within the spinal cord dorsal horn) and via descending pathways from supraspinal centres, involving several distinct neurotransmitter systems.</p>\n<p style=\"margin-top:12px\"><strong>A. TRUE</strong> — Although generally an excitatory neurotransmitter, acetylcholine is inhibitory within the pain pathway, acting mainly via muscarinic receptors (particularly M2/M4 subtypes) in the dorsal horn and supraspinally (e.g. periaqueductal grey). It has an antinociceptive/inhibitory effect on pain transmission &mdash; the pharmacological basis for the analgesic effect of intrathecal/epidural neostigmine (an acetylcholinesterase inhibitor that raises synaptic ACh levels).</p>\n<p style=\"margin-top:12px\"><strong>B. TRUE</strong> — Glycine is a major segmental inhibitory neurotransmitter in the dorsal horn, acting on glycine receptors (ligand-gated chloride channels) to hyperpolarise second-order neurons and inhibit nociceptive transmission; glycinergic disinhibition is implicated in mechanical allodynia.</p>\n<p style=\"margin-top:12px\"><strong>C. TRUE</strong> — GABA is a principal segmental inhibitory neurotransmitter in the dorsal horn, acting on GABA-A (ionotropic, fast) and GABA-B (metabotropic, slower) receptors to inhibit nociceptive transmission; loss of GABAergic tone is implicated in central sensitisation.</p>\n<p style=\"margin-top:12px\"><strong>D. FALSE</strong> — Glutamate is the principal <strong>excitatory</strong> neurotransmitter of the pain pathway, acting on NMDA, AMPA, and kainate receptors on dorsal horn neurons to mediate fast excitatory nociceptive transmission &mdash; the opposite of inhibitory.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> — Noradrenaline, released via descending pathways from the locus coeruleus, acts on alpha-2 adrenoreceptors on dorsal horn neurons and primary afferent terminals to inhibit nociceptive transmission &mdash; the pharmacological basis for the analgesic effects of clonidine and dexmedetomidine. Noradrenaline is generally an excitatory neurotransmitter but is inhibitory within the context of the pain pathway.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Inhibitory Neurotransmitters</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><table style=\"margin:0\"><tr><th colspan=\"3\" style=\"text-align:center\">Inhibitory neurotransmitters in the pain pathway</th></tr><tr><td><strong>Neurotransmitter</strong></td><td><strong>Full name(s)</strong></td><td><strong>Receptor in dorsal horn</strong></td></tr><tr><td><strong>GABA</strong></td><td>Gamma-aminobutyric acid</td><td>GABA<sub>A</sub>, GABA<sub>B</sub></td></tr><tr><td><strong>Gly</strong></td><td>Glycine</td><td>Glycine (strychnine-sensitive)</td></tr><tr><td><strong>Endorphins</strong></td><td>&beta;-endorphins</td><td>Opioid (&mu;&gt;&delta;,&kappa;)</td></tr><tr><td><strong>Enkephalins</strong></td><td>Met- and Leu-enkephalin, Enk-8</td><td>Opioid (&delta;&gt;&mu;,&kappa;)</td></tr><tr><td><strong>Dynorphins</strong></td><td>Dynorphin-A, Dynorphin-B</td><td>Opioid (&kappa;&gt;&mu;,&delta;)</td></tr><tr><td><strong>Endocannabinoids</strong></td><td>Anandamide (AEA), 2-arachidonoylglycerol (2-AG)</td><td>CB<sub>1</sub></td></tr><tr><td><strong>5-HT</strong></td><td>5-hydroxytryptamine (serotonin)</td><td>5-HT receptor subtypes 1&ndash;3</td></tr><tr><td><strong>NA</strong></td><td>Noradrenaline</td><td>&alpha;<sub>2</sub>-adrenergic</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_dorsal_horn_cytoarchitecture_001', 'MTF', '{"dateAdded":"2026-09-05","rotationIndex":74,"stem":"Regarding dorsal horn cytoarchitecture:","choices":["Galanin is excitatory in the dorsal horn","Most nociceptor afferents terminate in laminae III–V","Wide dynamic range (WDR) neurons only receive input from nociceptors","Lamina II (substantia gelatinosa) predominantly receives unmyelinated C-fibre input","Lamina I contains nociceptive-specific neurons"],"correct":[false,false,false,true,true],"explanation":"<p>The dorsal horn is organised into distinct laminae (Rexed laminae I&ndash;VI), each with characteristic afferent input and neuronal types, and this cytoarchitecture underpins how different classes of sensory information are processed and modulated.</p>\n<p style=\"margin-top:12px\"><strong>A. FALSE</strong> — Galanin is predominantly <strong>inhibitory/antinociceptive</strong> in the dorsal horn under normal physiological conditions, acting via <strong>GalR1</strong> receptors. Following peripheral nerve injury, galanin expression is markedly upregulated in primary afferents (a classic neuropathic pain marker), and its net effect becomes more complex &mdash; with some pronociceptive contribution via <strong>GalR2</strong> in the injured state &mdash; but as a general statement, galanin is not classified as excitatory.</p>\n<p style=\"margin-top:12px\"><strong>B. FALSE</strong> — Most nociceptive primary afferents (A&delta; and C fibres) terminate in the <strong>superficial dorsal horn &mdash; laminae I and II</strong>, not laminae III&ndash;V. Laminae III&ndash;V receive predominantly non-nociceptive (A&beta;, low-threshold mechanoreceptor) input, though lamina V does contain wide dynamic range neurons that also receive convergent nociceptive input.</p>\n<p style=\"margin-top:12px\"><strong>C. FALSE</strong> — Wide dynamic range (WDR) neurons, found mainly in lamina V, are defined precisely by receiving <strong>convergent input from both nociceptive (A&delta;, C fibre) and non-nociceptive (A&beta;, low-threshold) afferents</strong> &mdash; this convergence is the basis of their name and their proposed role in phenomena like referred pain and temporal summation (\"wind-up\").</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> — Lamina II (<strong>substantia gelatinosa</strong>) predominantly receives unmyelinated <strong>C-fibre</strong> input (along with some A&delta; input), and contains densely packed interneurons important in local modulation of nociceptive transmission, including the \"gate control\" mechanism.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> — Lamina I (marginal zone) contains <strong>nociceptive-specific neurons</strong>, which respond selectively to noxious stimuli and receive input mainly from A&delta; and C fibres, projecting via the spinothalamic tract to supraspinal pain-processing centres.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Dorsal horn</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Pain primary afferents enter the dorsal horn of the spinal cord, synapsing ipsilaterally with 2nd order neurons.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">In cross section, the spinal cord resembles an oval of white matter (myelinated axons), surrounding an H-shaped centre of grey matter (cell bodies).</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The grey matter is arranged into ten histological layers, or laminae, based on cytological architecture, known as Rexed''s laminae.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The dorsal horn is made up of laminae I&ndash;V.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"text-align:center\"><img src=\"images/rexed-laminae.png\" alt=\"Rexed laminae — spinal cord grey matter cross-section with laminae I–X labelled alongside a table of regions, nuclei and corresponding laminae\" style=\"max-width:100%;border-radius:10px;margin-top:0;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">A&delta; primary afferents terminate on laminae I and V, and C fibres terminate on lamina II, the substantia gelatinosa. A&delta; primary afferents synapse directly with secondary afferents that will eventually carry the pain signal to the thalamus. C fibres do not synapse directly with secondary afferents, but connect instead with interneurons that carry the signal on to secondary afferents in laminae I or V. These interneurons are important in modulation of the pain signal.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Visceral input differs in that fewer primary afferents activate a larger number of second order neurons, resulting in poorer localisation of pain. Visceral afferents also converge with somatic inputs, which may account for the phenomenon of referred pain.</p></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_central_sensitisation_001', 'MTF', '{"dateAdded":"2026-09-05","rotationIndex":75,"stem":"Regarding central sensitisation:","choices":["Wind-up is a heterosynaptic phenomenon","NMDA receptor activation is integral to the development of central sensitisation","Central sensitisation involves only peripheral changes","Central sensitisation can result in pain from normally non-painful stimuli","Central sensitisation is dependent on repeated or sustained afferent input (temporal summation)"],"correct":[false,true,false,true,true],"explanation":"<p>Central sensitisation is an activity-dependent increase in the excitability and synaptic efficacy of neurons in the central nociceptive pathways, following intense, repeated, or sustained peripheral input, leading to amplified pain responses that outlast and outsize the initiating stimulus.</p>\n<p style=\"margin-top:12px\"><strong>A. FALSE</strong> — Wind-up is a <strong>homosynaptic</strong> phenomenon &mdash; it refers to the progressive, frequency-dependent increase in dorsal horn neuron output in response to repeated stimulation of the <strong>same</strong> C-fibre input at a constant intensity, occurring at the same synapse. Heterosynaptic changes (affecting adjacent, non-stimulated synapses/inputs) are a feature of broader central sensitisation but not of wind-up itself, which is a more specific, shorter-lived electrophysiological phenomenon considered an early contributor to central sensitisation.</p>\n<p style=\"margin-top:12px\"><strong>B. TRUE</strong> — NMDA receptor activation is central (and essentially integral) to the development of central sensitisation &mdash; sustained/repetitive glutamate release removes the resting magnesium block of the NMDA receptor channel, allowing calcium influx and triggering intracellular signalling cascades that increase synaptic strength and neuronal excitability; NMDA receptor antagonists (e.g. ketamine) can attenuate or prevent central sensitisation.</p>\n<p style=\"margin-top:12px\"><strong>C. FALSE</strong> — Central sensitisation, by definition, involves <strong>changes within the central nervous system</strong> (spinal cord dorsal horn and supraspinal structures) &mdash; increased neuronal excitability, expanded receptive fields, and reduced inhibitory tone &mdash; rather than being confined to peripheral changes (which instead describe peripheral sensitisation, a distinct process).</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> — A hallmark clinical feature of central sensitisation is that it can produce pain in response to normally non-painful stimuli (<strong>allodynia</strong>) and exaggerated pain to normally painful stimuli (<strong>hyperalgesia</strong>), extending beyond the site of the original injury (secondary hyperalgesia).</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> — Central sensitisation typically develops in response to intense, repeated, or sustained nociceptive afferent input, with the temporal summation of C-fibre input (as seen in wind-up) considered an important triggering/early contributory mechanism leading to the more persistent state of central sensitisation.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Central sensitisation</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Definition</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Central sensitisation is an increase in the excitability and synaptic efficacy of neurons within central nociceptive pathways (spinal dorsal horn and supraspinal structures).</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">It happens following intense, repetitive, or sustained peripheral nociceptive input. It results in pain responses that are amplified, prolonged, and spatially extended beyond what the original stimulus/injury would predict.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Triggering Process</div><table style=\"margin:0\"><tr><th>#</th><th>Stage</th><th>Detail</th></tr><tr><td>1</td><td><strong>Intense / sustained nociceptor activation</strong></td><td>From tissue injury or inflammation, causing repeated, high-frequency C-fibre afferent discharge into the dorsal horn.</td></tr><tr><td>2</td><td><strong>Glutamate and neuropeptide release</strong></td><td>Presynaptic terminals of primary afferents release glutamate (acting on AMPA and NMDA receptors) along with co-transmitters substance P (acting on NK1 receptors) and calcitonin gene-related peptide (CGRP).</td></tr><tr><td>3</td><td><strong>Wind-up</strong></td><td>Repeated C-fibre stimulation at constant intensity produces a progressive, frequency-dependent increase in dorsal horn neuron output at the <em>same</em> synapse; this is a short-lived electrophysiological precursor/contributor rather than central sensitisation itself.</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><table style=\"margin:0\"><tr><th>Key Molecular Mechanism &mdash; NMDA Receptor Unblocking</th></tr><tr><td>At rest, the NMDA receptor channel is blocked by <strong>magnesium (Mg<sup>2+</sup>)</strong> in a voltage-dependent manner.</td></tr><tr><td>Sustained depolarisation (from repetitive AMPA/NK1 receptor activation via glutamate/substance P) relieves this Mg<sup>2+</sup> block.</td></tr><tr><td>This allows <strong>calcium influx</strong> through the now-unblocked NMDA receptor.</td></tr><tr><td>Intracellular calcium activates second-messenger cascades (e.g. <strong>protein kinase C, CaMKII</strong>), leading to: phosphorylation of AMPA and NMDA receptors &rarr; increased receptor sensitivity/conductance; increased trafficking/insertion of AMPA receptors into the postsynaptic membrane &rarr; increased synaptic strength; activation of immediate early genes (e.g. c-fos) &rarr; longer-term transcriptional changes supporting sustained sensitisation.</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Additional Contributing Mechanisms</div><table style=\"margin:0\"><tr><th>Mechanism</th><th>Detail</th></tr><tr><td><strong>Loss of inhibitory tone (disinhibition)</strong></td><td>Reduction in GABAergic and glycinergic inhibitory interneuron activity in the dorsal horn, removing normal \"braking\" control on nociceptive transmission.</td></tr><tr><td><strong>Microglial and astrocyte activation</strong></td><td>Release of pro-inflammatory cytokines (TNF-alpha, IL-1beta, IL-6) and other mediators that further enhance neuronal excitability &mdash; an important contributor to the transition from acute to chronic/neuropathic pain states.</td></tr><tr><td><strong>Expansion of receptive fields</strong></td><td>Dorsal horn neurons begin responding to input from a wider area than their original receptive field, contributing to spread of pain beyond the original injury site.</td></tr><tr><td><strong>Reduced activation threshold</strong></td><td>Neurons respond to previously subthreshold (non-noxious) input.</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical Manifestations</div><table style=\"margin:0\"><tr><th>Feature</th><th>Description</th></tr><tr><td><strong>Allodynia</strong></td><td>Pain from normally non-painful stimuli (e.g. light touch).</td></tr><tr><td><strong>Hyperalgesia</strong></td><td>Exaggerated pain response to normally painful stimuli.</td></tr><tr><td><strong>Secondary hyperalgesia</strong></td><td>Pain sensitivity extending to undamaged tissue surrounding the original injury site.</td></tr><tr><td><strong>Temporal summation</strong></td><td>Increasing pain perception with repeated stimuli of constant intensity (clinical correlate of wind-up).</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><table style=\"margin:0\"><tr><th>Clinical / Pharmacological Relevance</th></tr><tr><td><strong>NMDA receptor antagonists</strong> (ketamine, magnesium, methadone) can attenuate or help prevent the development of central sensitisation &mdash; the rationale for their use in chronic pain and opioid-tolerant states.</td></tr><tr><td>Central sensitisation is a key mechanism underlying <strong>chronic pain states</strong> where pain persists or amplifies beyond expected tissue healing time, and is central to understanding conditions such as fibromyalgia, chronic low back pain, and neuropathic pain syndromes.</td></tr><tr><td>Distinguished from <strong>peripheral sensitisation</strong>, which is increased sensitivity of the peripheral nervous system to stimuli &mdash; lowered threshold/increased responsiveness of the primary nociceptor terminal itself (via the \"inflammatory soup\" &mdash; prostaglandins, bradykinin, ATP, potassium, etc.). The two processes are complementary but occur at different anatomical sites.</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_conventional_tens_001', 'MTF', '{"dateAdded":"2026-09-05","rotationIndex":76,"stem":"Regarding conventional TENS (Transcutaneous Electrical Nerve Stimulation):","choices":["Typical frequency is 50–100 Hz","Typical pulse width is 50–200 milliseconds","Contraindicated in patients with epilepsy","Works via modulation of spinal GABA release","Contraindicated in patients with pacemakers"],"correct":[true,false,false,false,true],"explanation":"<p>Conventional TENS uses high-frequency, low-intensity stimulation to preferentially activate large-diameter A&beta; fibres, producing analgesia mainly through the spinal gate-control mechanism and opioid-mediated pathways, and understanding its parameters and safety profile is frequently tested.</p>\n<p style=\"margin-top:12px\"><strong>A. TRUE</strong> — Conventional TENS typically uses a <strong>high frequency of 50&ndash;100 Hz</strong>, delivered at low intensity, producing a comfortable tingling/buzzing sensation without visible muscle contraction.</p>\n<p style=\"margin-top:12px\"><strong>B. FALSE</strong> — The typical pulse <strong>width</strong> (duration) for conventional TENS is in the range of <strong>50&ndash;200 microseconds</strong>, not milliseconds &mdash; this is a common unit-based exam trap; a pulse width of milliseconds would be several orders of magnitude too long and outside standard TENS parameters.</p>\n<p style=\"margin-top:12px\"><strong>C. FALSE</strong> — TENS manufacturers list cardiac pacemakers, pregnancy, and epilepsy as contraindications largely because it may be difficult to exclude TENS as a cause of a problem from a legal perspective. In practice, TENS can be used safely in patients with epilepsy; there is no established mechanism by which peripheral transcutaneous electrical stimulation would provoke seizure activity. Recognised contraindications instead include use over the carotid sinus, in patients with cardiac pacemakers/implantable defibrillators, and over the pregnant abdomen.</p>\n<p style=\"margin-top:12px\"><strong>D. FALSE</strong> — Conventional TENS does <strong>not</strong> work primarily through GABA modulation; its main proposed mechanisms are the <strong>gate control theory</strong> (activation of large A&beta; fibres inhibiting nociceptive transmission at the dorsal horn) and spinal <strong>delta-opioid receptor</strong> activation.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> — TENS is contraindicated (or requires specialist caution) in patients with cardiac pacemakers or implantable cardioverter-defibrillators (ICDs), due to the risk of electrical interference with device function; TENS electrodes should also not be placed near the device itself even where cautious use is considered acceptable.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">TENS</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Transcutaneous Electrical Nerve Stimulation (TENS) is a non-invasive, low-cost, patient-controlled method of pain relief. A small battery-powered pulse generator delivers electrical pulses to the skin through adhesive surface electrodes.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Parameters that can be modified on a TENS machine include pulse duration (in microseconds), pulse frequency (in Hz or pulses/sec) and pulse amplitude (in milliamperes).</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Types of TENS</div><table style=\"margin:0\"><tr><th>Type</th><th>Frequency</th><th>Intensity</th><th>Fibres activated</th><th>Proposed mechanism</th></tr><tr><td><strong>Conventional TENS</strong></td><td>High (~50&ndash;100 Hz)</td><td>Low &mdash; comfortable tingling, no visible contraction</td><td>Large-diameter A&beta; afferents</td><td>Segmental gate-control inhibition of dorsal horn transmission; spinal delta-opioid receptor involvement</td></tr><tr><td><strong>Acupuncture-like TENS (AL-TENS)</strong></td><td>Low (~2&ndash;4 Hz)</td><td>High &mdash; visible muscle twitching</td><td>Smaller A&delta; afferents / motor efferents</td><td>Extrasegmental, opioid-mediated (mu-receptor) analgesia via activation of descending inhibitory pathways</td></tr><tr><td><strong>Intense TENS</strong></td><td>High</td><td>Very high &mdash; at or near the limit of tolerability</td><td>Small-diameter A&delta; (and some C) fibres</td><td>Counter-irritation / hyperstimulation analgesia; typically used briefly for short, painful procedures (e.g. wound dressing changes, injections) rather than continuously, as tolerance to the high intensity limits prolonged application</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">TENS Contraindications</div><table style=\"margin:0\"><tr><th>Contraindication / precaution</th><th>Reason</th></tr><tr><td>Cardiac implantable devices</td><td>Pacemakers and implantable cardioverter-defibrillators &mdash; electrical interference can disrupt device sensing/pacing.</td></tr><tr><td>Over the carotid sinus</td><td>Risk of provoking a vasovagal/hypotensive response.</td></tr><tr><td>Over the anterior neck / larynx</td><td>Risk of laryngospasm or interference with airway reflexes.</td></tr><tr><td>Pregnancy</td><td>Avoid placement over the abdomen or lower back, particularly in early pregnancy, due to theoretical uterine stimulation risk (direct evidence of harm is limited).</td></tr><tr><td>Active malignancy at the treatment site</td><td>Theoretical concern regarding electrical stimulation of tumour tissue, though evidence is limited.</td></tr><tr><td>Broken/irritated skin, adhesive allergy</td><td>Local skin precautions.</td></tr><tr><td>Driving, operating machinery, or sleep</td><td>Devices should never be applied then, given the reliance on patient feedback for safe intensity titration.</td></tr><tr><td>Dysaesthesia / diminished sensation</td><td>TENS should not be applied to skin with diminished sensation &mdash; nerve damage is likely to reduce effectiveness and the patient may be unaware that high-intensity currents are causing skin irritation. Caution with mechanical allodynia, as TENS may exacerbate the pain.</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Effectiveness</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Clinical experience suggests that TENS may relieve any type of chronic pain, yet systematic reviews are inconclusive for chronic pain, low back pain, cancer-related pain, rheumatoid arthritis of the hand, post-stroke shoulder pain, whiplash and mechanical neck disorders, and chronic recurrent headache. Meta-analyses for osteoarthritic knee pain and for chronic musculoskeletal pain have been more positive, suggesting that TENS is superior to sham TENS for pain and stiffness. Non-randomised controlled clinical trials have found benefit for many types of chronic pain.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">NICE guidance does <strong>not</strong> recommend routinely offering TENS for chronic low back pain.</p></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_amitriptyline_001', 'MTF', '{"dateAdded":"2026-09-05","rotationIndex":77,"stem":"Regarding amitriptyline:","choices":["Blocks sodium channels within the CNS","Works via a potassium channel-mediated mechanism","Has low anticholinergic properties","Is beneficial for depression at low doses","Inhibits reuptake of both serotonin and noradrenaline"],"correct":[true,false,false,false,true],"explanation":"<p>Amitriptyline is a tricyclic antidepressant (TCA) with a broad, multimodal mechanism of action relevant to both its analgesic and antidepressant effects, but also carries a significant side-effect burden that limits its use, particularly in older or frailer patients.</p>\n<p style=\"margin-top:12px\"><strong>A. TRUE</strong> — Amitriptyline blocks <strong>voltage-gated sodium channels</strong> both peripherally and centrally, contributing a local anaesthetic-like, membrane-stabilising effect that is thought to underlie part of its analgesic action in neuropathic pain, independent of its monoamine reuptake inhibition.</p>\n<p style=\"margin-top:12px\"><strong>B. FALSE</strong> — Potassium channel blockade is not a recognised principal mechanism of amitriptyline''s action; its main mechanisms are monoamine reuptake inhibition and sodium channel blockade, along with antagonism at several other receptors.</p>\n<p style=\"margin-top:12px\"><strong>C. FALSE</strong> — Amitriptyline has <strong>high (not low) anticholinergic properties</strong>, causing recognised antimuscarinic side effects such as dry mouth, blurred vision, constipation, urinary retention, and confusion &mdash; particularly problematic in elderly patients, and a key reason for caution/avoidance in this population.</p>\n<p style=\"margin-top:12px\"><strong>D. FALSE</strong> — Amitriptyline''s analgesic effect for neuropathic pain occurs at <strong>low doses</strong> (typically 10&ndash;75 mg), well below the doses required for an <strong>antidepressant</strong> effect (typically 150 mg or more).</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> — Amitriptyline acts as a <strong>non-selective monoamine reuptake inhibitor</strong>, inhibiting reuptake of both <strong>serotonin and noradrenaline</strong> at the presynaptic terminal, enhancing descending inhibitory pain pathways &mdash; this is central to both its analgesic and antidepressant mechanisms.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Amitriptyline</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>Class:</strong> Tricyclic antidepressant (TCA)</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Mechanism of Action</div><table style=\"margin:0\"><tr><th>Mechanism</th><th>Detail</th></tr><tr><td><strong>Non-selective monoamine reuptake inhibitor</strong></td><td>Blocks presynaptic reuptake of both serotonin (5-HT) and noradrenaline, enhancing descending inhibitory pain pathways and mood regulation.</td></tr><tr><td><strong>Sodium channel blockade (central &amp; peripheral)</strong></td><td>Local anaesthetic-like, membrane-stabilising effect contributing to analgesia, independent of monoamine effects.</td></tr><tr><td>Muscarinic (antimuscarinic) antagonism</td><td>High affinity &mdash; drives much of the side-effect profile.</td></tr><tr><td>Histamine H1 antagonism</td><td>Sedative effect.</td></tr><tr><td>Alpha-1 adrenergic antagonism</td><td>Postural hypotension.</td></tr><tr><td>NMDA receptor antagonism</td><td>Some activity, contributing to the analgesic effect.</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Dose-Dependent Effect</div><table style=\"margin:0\"><tr><th>Indication</th><th>Typical dose</th><th>Onset</th></tr><tr><td>Neuropathic pain</td><td>Low dose (10&ndash;50 mg, often at night)</td><td>Days to ~2 weeks</td></tr><tr><td>Depression</td><td>Higher dose (150 mg+)</td><td>2&ndash;4 weeks</td></tr></table><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Analgesic benefit occurs independently of, and at doses well below, those needed for antidepressant effect.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Pharmacokinetics</div><table style=\"margin:0\"><tr><th>Parameter</th><th>Detail</th></tr><tr><td>Absorption</td><td>Well absorbed orally; significant first-pass hepatic metabolism, giving relatively low and variable oral bioavailability.</td></tr><tr><td>Metabolism</td><td>Hepatic, primarily via CYP2D6 (and CYP1A2, CYP3A4) &rarr; demethylation to nortriptyline, itself a pharmacologically active tricyclic antidepressant/analgesic (more noradrenaline-selective than the parent drug).</td></tr><tr><td>Protein binding</td><td>Highly protein-bound (~95%).</td></tr><tr><td>Volume of distribution</td><td>Large (highly lipophilic, extensive tissue distribution) &mdash; relevant to the difficulty of dialysing it out in overdose.</td></tr><tr><td>Half-life</td><td>Long and variable, roughly 10&ndash;28 hours (contributes to once-daily dosing, typically at night due to sedation).</td></tr><tr><td>Excretion</td><td>Renal excretion of (conjugated) metabolites, with some faecal elimination.</td></tr><tr><td>Genetic variability</td><td>CYP2D6 polymorphism causes significant interpatient variability &mdash; poor metabolisers may accumulate higher levels at standard doses (increasing side-effect/toxicity risk); ultra-rapid metabolisers may have reduced efficacy at standard doses.</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><table style=\"margin:0\"><tr><th>Clinical Uses</th></tr><tr><td>Neuropathic pain (first/second-line agent per NICE guidance)</td></tr><tr><td>Chronic pain syndromes (e.g. fibromyalgia &mdash; off-label)</td></tr><tr><td>Migraine prophylaxis</td></tr><tr><td>Depression (higher dose)</td></tr><tr><td>Insomnia (off-label, low dose, due to sedative H1 antagonism)</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Side Effects (largely receptor-driven)</div><table style=\"margin:0\"><tr><th>System</th><th>Effects</th></tr><tr><td>Anticholinergic</td><td>Dry mouth, blurred vision, constipation, urinary retention, confusion (especially in the elderly).</td></tr><tr><td>Antihistaminergic</td><td>Sedation, weight gain.</td></tr><tr><td>Alpha-1 blockade</td><td>Postural hypotension.</td></tr><tr><td>Cardiac</td><td>QTc prolongation, arrhythmia risk (sodium/potassium channel effects) &mdash; caution in cardiac disease.</td></tr><tr><td>CNS</td><td>Lowers the seizure threshold.</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><table style=\"margin:0\"><tr><th>Contraindications / Cautions</th></tr><tr><td>Recent myocardial infarction</td></tr><tr><td>Arrhythmias, heart block</td></tr><tr><td>Severe hepatic impairment</td></tr><tr><td>Concurrent MAOI use (risk of serotonin syndrome / hypertensive crisis)</td></tr><tr><td>Caution in elderly patients (anticholinergic burden, falls risk, sedation)</td></tr><tr><td>Caution in narrow-angle glaucoma and urinary retention (e.g. prostatic hypertrophy)</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><table style=\"margin:0\"><tr><th>Overdose</th></tr><tr><td>Classic and dangerous in TCA overdose: cardiotoxicity (sodium channel blockade &rarr; wide QRS, arrhythmias), seizures, severe anticholinergic toxicity, coma.</td></tr><tr><td>Sodium bicarbonate is used in the management of TCA-induced cardiotoxicity (widened QRS).</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_botulinum_toxin_001', 'MTF', '{"dateAdded":"2026-09-05","rotationIndex":78,"stem":"Regarding botulinum toxin:","choices":["Should be stored at 18°C","Onset of clinical effect typically takes 1–2 weeks","Licensed for use in episodic migraine","Can cause flu-like symptoms","Acts as an agonist at the acetylcholine receptor"],"correct":[false,true,false,true,false],"explanation":"<p>Botulinum toxin is a potent neurotoxin used therapeutically in several pain and movement disorder conditions, with specific storage, onset, licensing, and mechanistic properties that are frequently tested.</p>\n<p style=\"margin-top:12px\"><strong>A. FALSE</strong> — Botulinum toxin requires <strong>refrigerated storage</strong>, typically between <strong>2&ndash;8&deg;C</strong> (in a fridge), not at 18&deg;C; it must be protected from heat and light to preserve potency, and once reconstituted has a limited shelf life requiring prompt use.</p>\n<p style=\"margin-top:12px\"><strong>B. TRUE</strong> — The clinical effect of botulinum toxin typically has a <strong>delayed onset</strong>, becoming apparent over <strong>1&ndash;2 weeks</strong> following injection, as it takes time for the toxin to be internalised and to block neurotransmitter release at the neuromuscular junction / nerve terminal.</p>\n<p style=\"margin-top:12px\"><strong>C. FALSE</strong> — Botulinum toxin is licensed for <strong>chronic migraine</strong> (headache on &ge;15 days/month), <strong>not episodic migraine</strong>, where the evidence does not support its use.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> — Flu-like symptoms (malaise, myalgia, low-grade fever) are a recognised, generally mild and self-limiting side effect following botulinum toxin injection.</p>\n<p style=\"margin-top:12px\"><strong>E. FALSE</strong> — Botulinum toxin does <strong>not</strong> act as an agonist at the acetylcholine receptor &mdash; it works by cleaving <strong>SNARE proteins</strong> (e.g. SNAP-25) required for vesicular fusion, thereby preventing acetylcholine release from the presynaptic nerve terminal at the neuromuscular junction, producing a chemodenervation effect (flaccid paralysis) rather than receptor agonism.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Botulinum Toxin</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>Class:</strong> Neurotoxin produced by <em>Clostridium botulinum</em>; multiple serotypes exist (A&ndash;G), with type A (onabotulinumtoxinA / BoNT-A) most widely used clinically.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><table style=\"margin:0\"><tr><th>Mechanism of Action</th></tr><tr><td>Toxin is taken up at the presynaptic nerve terminal (peripheral cholinergic synapses, including the neuromuscular junction).</td></tr><tr><td>Cleaves <strong>SNARE proteins</strong> (SNAP-25 for type A; VAMP/synaptobrevin for type B) required for vesicle docking and fusion.</td></tr><tr><td>This <strong>prevents acetylcholine release</strong> from the presynaptic terminal, producing <strong>chemodenervation</strong> &mdash; a temporary, reversible flaccid paralysis of the affected muscle, or reduced glandular secretion where used for sweat glands.</td></tr><tr><td>Also has emerging evidence of a direct <strong>antinociceptive effect</strong> independent of muscle paralysis, via inhibition of release of pain-related neuropeptides (substance P, CGRP, glutamate) from sensory nerve terminals &mdash; relevant to its analgesic use (e.g. chronic migraine).</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Pharmacokinetics / Handling</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td>Storage</td><td>Refrigerated (2&ndash;8&deg;C), protected from light; must not be frozen.</td></tr><tr><td>Reconstituted shelf life</td><td>Limited &mdash; should be used promptly (typically within a few hours, per manufacturer guidance).</td></tr><tr><td>Distribution</td><td>Acts locally at the injection site with minimal systemic absorption at standard therapeutic doses.</td></tr><tr><td>Onset of effect</td><td>Delayed, typically 1&ndash;2 weeks.</td></tr><tr><td>Duration of effect</td><td>Typically 3&ndash;4 months, as new nerve terminal sprouting and SNARE protein turnover restore neurotransmission, necessitating repeat injections for sustained benefit.</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Indications</div><table style=\"margin:0\"><tr><th>Area</th><th>Uses</th></tr><tr><td>Pain medicine</td><td>Chronic migraine (&ge;15 headache days/month, &ge;8 of which are migrainous) &mdash; NOT licensed for episodic migraine; myofascial pain syndrome / trigger point injections (off-label); emerging/off-label interest in neuropathic pain, complex regional pain syndrome, and post-herpetic neuralgia.</td></tr><tr><td>Neurology / movement disorders</td><td>Spasticity (post-stroke, cerebral palsy, multiple sclerosis); cervical dystonia; blepharospasm; hemifacial spasm.</td></tr><tr><td>Other established uses</td><td>Hyperhidrosis (axillary, palmar); detrusor overactivity / overactive bladder; sialorrhoea; achalasia (oesophageal sphincter injection); cosmetic use (glabellar lines, crow''s feet).</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><table style=\"margin:0\"><tr><th>Side Effects</th></tr><tr><td>Flu-like symptoms (malaise, myalgia, mild fever) &mdash; generally mild, self-limiting.</td></tr><tr><td>Localised pain / bruising at the injection site.</td></tr><tr><td>Unintended weakness of adjacent muscles (spread of effect) &mdash; e.g. ptosis with facial injections, dysphagia with cervical dystonia treatment.</td></tr><tr><td>Rarely, systemic spread causing generalised weakness (particularly at high doses or in patients with neuromuscular junction disorders).</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><table style=\"margin:0\"><tr><th>Contraindications</th></tr><tr><td>Known hypersensitivity to botulinum toxin or formulation components.</td></tr><tr><td>Infection at the proposed injection site.</td></tr><tr><td>Neuromuscular junction disorders (e.g. myasthenia gravis, Lambert-Eaton syndrome) &mdash; increased risk of profound/generalised weakness.</td></tr><tr><td>Pregnancy and breastfeeding (generally avoided, limited safety data).</td></tr><tr><td>Caution with concurrent aminoglycoside use (can potentiate neuromuscular blockade).</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_mri_physics_001', 'MTF', '{"dateAdded":"2026-09-05","rotationIndex":79,"stem":"MRI:","choices":["Works through isotopes of water","T1-weighted imaging is better than T2 for grey-white matter differentiation","T1-weighted imaging is better than T2 for detecting oedema","T2-weighted imaging is better than T1 for assessing CSF","T1 and T2 relaxation times are related to the radiofrequency pulse frequency used"],"correct":[false,true,false,true,false],"explanation":"<p>MRI generates images based on the behaviour of hydrogen protons (not isotopes) within a strong magnetic field, and the relative weighting of the sequence (T1 vs T2) determines how different tissue types and pathologies are best visualised.</p>\n<p style=\"margin-top:12px\"><strong>A. FALSE</strong> — MRI works through the magnetic properties of <strong>hydrogen protons</strong> (particularly abundant in water and fat molecules) aligning within a strong external magnetic field and then relaxing back to equilibrium after a radiofrequency pulse.</p>\n<p style=\"margin-top:12px\"><strong>B. TRUE</strong> — <strong>T1-weighted</strong> images provide superior anatomical detail and are generally considered better for <strong>grey-white matter differentiation</strong>, with grey matter appearing darker and white matter appearing brighter due to differing fat/myelin content affecting T1 relaxation.</p>\n<p style=\"margin-top:12px\"><strong>C. FALSE</strong> — <strong>T2-weighted</strong> imaging is more sensitive for detecting <strong>oedema</strong>, as tissue/fluid with high water content appears bright on T2 sequences, making it the preferred sequence for identifying oedematous or inflammatory pathology.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> — <strong>T2-weighted</strong> imaging is better for assessing <strong>CSF</strong> and fluid-containing structures, as CSF appears bright (hyperintense) on T2 sequences, in contrast to its dark appearance on T1-weighted images.</p>\n<p style=\"margin-top:12px\"><strong>E. FALSE</strong> — T1 and T2 are <strong>relaxation times</strong> (measured in milliseconds) describing how quickly protons return to equilibrium after an RF pulse &mdash; T1 (longitudinal / spin-lattice relaxation) and T2 (transverse / spin-spin relaxation). They are intrinsic tissue properties related to the magnetic environment and interactions between protons and surrounding molecules, not directly defined by or equivalent to the radiofrequency pulse frequency itself.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">MRI</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"position:relative;width:100%;padding-top:56.25%;border-radius:10px;overflow:hidden;background:#000\">\n          <iframe src=\"https://www.youtube.com/embed/jLnuPKhKXVM?start=302\" title=\"How MRI Works\" style=\"position:absolute;inset:0;width:100%;height:100%;border:0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen></iframe>\n        </div><p style=\"margin:14px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">MRI exploits the magnetic behaviour of <strong>hydrogen protons</strong> (abundant in water and fat throughout the body) when placed in a strong external magnetic field. Protons align with the field, and a radiofrequency (RF) pulse is applied to temporarily knock them out of alignment. As protons \"relax\" back to equilibrium after the RF pulse is switched off, they emit signals that are detected and reconstructed into an image.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Key Relaxation Parameters</div><table style=\"margin:0\"><tr><th>Parameter</th><th>Definition</th></tr><tr><td><strong>T1</strong></td><td>Time for longitudinal magnetisation to recover (protons realign with the main magnetic field).</td></tr><tr><td><strong>T2</strong></td><td>Time for transverse magnetisation to decay (protons lose phase coherence with each other).</td></tr></table><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Different tissues have characteristic T1 and T2 relaxation times based on their molecular environment (fat content, water content, protein binding), which is the basis of tissue contrast in MRI.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">T1 vs T2 Weighted Imaging</div><table style=\"margin:0\"><tr><th>Feature</th><th>T1-weighted</th><th>T2-weighted</th></tr><tr><td>Fat</td><td>Bright</td><td>Intermediate/bright (less so than T1)</td></tr><tr><td>Water / CSF / oedema</td><td>Dark</td><td>Bright</td></tr><tr><td>Best for</td><td>Anatomical detail, grey-white matter differentiation</td><td>Pathology detection &mdash; oedema, inflammation, tumours, CSF assessment</td></tr><tr><td>Mnemonic</td><td>\"T1 = ana<strong>T</strong>omy\"</td><td>\"T2 = pathology / wa<strong>T</strong>er\"</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"text-align:center\"><img src=\"images/mri-t1-t2-brain-comparison.png\" alt=\"Axial brain MRI comparison — T1-weighted (anatomy/structure: white matter bright, CSF dark) versus T2-weighted (pathology/disease: CSF bright, white matter dark grey), with a feature table for CSF, white matter, fat and oedema/tumour\" style=\"max-width:100%;border-radius:10px;margin-top:0;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"text-align:center\"><img src=\"images/mri-t1-t2-lumbar-spine.png\" alt=\"Sagittal lumbar spine MRI — T1-weighted and T2-weighted unlabelled images with an annotated reference (bone marrow, spinal cord, CSF, epidural fat, subcutaneous fat, nucleus pulposus, bone cortex) and a table of T1 vs T2 signal for fat, CSF and bone\" style=\"max-width:100%;border-radius:10px;margin-top:0;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Common Sequences (Beyond Basic T1/T2)</div><table style=\"margin:0\"><tr><th>Sequence</th><th>Detail</th></tr><tr><td><strong>STIR</strong> (Short Tau Inversion Recovery)</td><td>Fat-suppression sequence; highly sensitive for oedema / bone marrow pathology (commonly used in spinal imaging for pain medicine).</td></tr><tr><td><strong>FLAIR</strong> (Fluid-Attenuated Inversion Recovery)</td><td>Suppresses CSF signal while retaining sensitivity to oedema/lesions &mdash; useful in brain imaging (e.g. MS plaques).</td></tr><tr><td><strong>Diffusion-weighted imaging (DWI)</strong></td><td>Detects restricted water molecule diffusion &mdash; highly sensitive for acute ischaemic stroke.</td></tr><tr><td><strong>Contrast-enhanced MRI</strong> (gadolinium-based)</td><td>Highlights areas of blood-brain barrier breakdown, inflammation, tumour, or infection (e.g. helps distinguish recurrent disc herniation from post-surgical scar tissue in the spine).</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_imaging_modalities_001', 'MTF', '{"dateAdded":"2026-09-05","rotationIndex":80,"stem":"Regarding imaging modalities:","choices":["CT works through the spin of molecules","Functional MRI (fMRI) helps detect changes in blood flow","MRI encephalogram can detect changes over a very short period","PET involves injection of a radioactive tracer that is taken up by metabolically active cells","Ultrasound imaging works via the piezoelectric effect"],"correct":[false,true,true,true,true],"explanation":"<p>Different imaging modalities rely on fundamentally different physical principles &mdash; X-ray attenuation, proton behaviour in a magnetic field, magnetic fields generated by neuronal activity, radiotracer uptake, and the piezoelectric effect &mdash; and distinguishing them is frequently tested.</p>\n<p style=\"margin-top:12px\"><strong>A. FALSE</strong> — CT (Computed Tomography) works through <strong>differential attenuation of X-rays</strong> as they pass through tissues of varying density, reconstructed mathematically into cross-sectional images &mdash; it does <strong>not</strong> rely on the spin of molecules/protons, which is instead the underlying principle of MRI.</p>\n<p style=\"margin-top:12px\"><strong>B. TRUE</strong> — Functional MRI (fMRI) detects changes in <strong>blood flow and oxygenation</strong> (the BOLD signal &mdash; Blood Oxygen Level Dependent contrast), reflecting regional neuronal activity, since active brain regions receive increased oxygenated blood flow relative to oxygen extraction, altering the local magnetic signal.</p>\n<p style=\"margin-top:12px\"><strong>C. TRUE</strong> — Magnetoencephalography (MEG) directly measures the tiny magnetic fields produced by neuronal electrical activity, allowing detection of functional brain changes over very short (millisecond) time periods, offering excellent temporal resolution (superior to fMRI, which has better spatial but poorer temporal resolution).</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> — PET (Positron Emission Tomography) involves injecting a <strong>radioactive tracer</strong> (commonly a radiolabelled glucose analogue, FDG) which is preferentially taken up by <strong>metabolically active cells</strong> (e.g. tumour cells, active neurons); the emitted positrons are detected to construct functional/metabolic images, often combined with CT (PET-CT) for anatomical correlation.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> — Ultrasound generates images using the <strong>piezoelectric effect</strong> &mdash; a transducer crystal converts electrical energy into high-frequency sound waves, which are reflected differentially by tissue interfaces and reconverted into electrical signals to form an image; unlike CT/MRI, no ionising radiation or strong magnetic field is involved.</p>"}'::jsonb, 'published')
  on conflict (id) do nothing;

